{
  "items": [
    {
      "title": "Eurostat – Government Revenue, Expenditure and Main Aggregates",
      "url_or_doi": "https://doi.org/10.2908/gov_10a_main",
      "justification": "One of the most comprehensive datasets for studying German fiscal policy during 2010–2019. Provides annual government revenue, total expenditure, taxes, social contributions, fiscal deficits and surpluses, and other public finance indicators. Includes breakdowns by central, state and local government, as well as social security funds. Data are available in euros and as percentages of GDP, making the dataset particularly useful for examining Germany's fiscal consolidation and budget surplus policies during the 2010s."
    },
    {
      "title": "Eurostat – General Government Expenditure by Function (COFOG)",
      "url_or_doi": "https://doi.org/10.2908/gov_10a_exp",
      "justification": "Provides detailed annual public expenditure data for Germany throughout the 2010s, classified by government function. Categories include education, healthcare, defense, social protection, infrastructure, environmental protection and economic affairs. Particularly useful for analyzing changes in German spending priorities, public investment and the allocation of government resources between 2010 and 2019."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – Public Finance: Expenditure, Revenue and Financial Balance",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Government/Public-Finance/Expenditure-Revenue-And-Financial-Balance-Of-Public-Budgets/Tables/expenditure-revenue-balance.html",
      "justification": "Official German government statistics providing annual public expenditure, revenue and budget balances, including the complete 2010–2019 period. Figures are expressed in billions of euros. Particularly relevant for examining Germany's transition from a substantial public deficit in 2010 to budget surpluses later in the decade. Researchers should note methodological changes affecting comparisons across years."
    },
    {
      "title": "Destatis GENESIS-Online – Government Revenue, Expenditure and Financing Balance",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/81000/table/81000-0031/search/s/ODEwMDA%3D",
      "justification": "Official national accounts dataset published by Germany's Federal Statistical Office. Contains annual government revenue, expenditure and financing balance statistics, including observations from the 2010s. Useful for analyzing the evolution of German fiscal policy, government financing requirements and changes in public-sector financial performance."
    },
    {
      "title": "Destatis GENESIS-Online – Tax Revenue by Type of Tax",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/url/ccfa4350",
      "justification": "Official German tax revenue statistics providing annual figures by tax category. Includes information on different sources of taxation, enabling analysis of changes in Germany's revenue structure during the 2010s. Particularly useful for studying income taxation, consumption taxes, corporate taxation and the contribution of different tax instruments to public finances."
    },
    {
      "title": "Deutsche Bundesbank – Public Finances Statistics",
      "url_or_doi": "https://www.bundesbank.de/en/statistics/public-finances",
      "justification": "The German central bank provides historical statistical series covering government revenue, expenditure, fiscal balances and public finances. Includes national accounts measures and budgetary statistics. Valuable for investigating German fiscal policy during 2010–2019, including expenditure developments, revenue growth and government borrowing. Particularly useful as an authoritative national source alongside Destatis."
    },
    {
      "title": "International Monetary Fund – Government Finance Statistics",
      "url_or_doi": "https://data.imf.org/Datasets/QGFS",
      "justification": "Internationally standardized government finance statistics covering government revenue, expenditure, fiscal deficits, financing transactions, assets and liabilities. Provides information for different levels of government and supports analysis of Germany's public finances during the 2010s. Particularly useful for comparing Germany's fiscal performance with that of other advanced economies and examining fiscal trends using harmonized definitions."
    },
    {
      "title": "OECD – Revenue Statistics 2021: Country Tables, 1990–2019",
      "url_or_doi": "https://www.oecd.org/en/publications/revenue-statistics-2021_6e87f932-en/full-report/component-8.html",
      "justification": "OECD historical tax revenue statistics covering Germany and other member countries through 2019. Includes tax revenue as a percentage of GDP, revenue by major tax category and taxation by level of government. Particularly relevant for examining Germany's tax structure, tax burden and changes in public revenue during the 2010s. Supports international comparisons of fiscal and taxation policies."
    },
    {
      "title": "World Bank – World Development Indicators: Government Expense (% of GDP), Germany",
      "url_or_doi": "https://data.worldbank.org/indicator/GC.XPN.TOTL.GD.ZS?locations=DE",
      "justification": "Provides historical government expense as a percentage of GDP for Germany, including observations covering 2010–2019. Useful for analyzing changes in public expenditure relative to economic output and comparing Germany with other countries. The standardized indicator supports research on fiscal policy, the size of government and public spending trends over time."
    },
    {
      "title": "Eurostat – Tax Revenue Statistics: Taxes and Social Contributions",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/gov_10a_taxag/default/table?lang=en",
      "justification": "Provides annual statistics on government revenue from taxes and social contributions for European countries, including Germany. Relevant indicators include the overall tax burden and the composition of tax and social contribution receipts. Particularly useful for investigating changes in Germany's tax-to-GDP ratio, revenue mobilization and the structure of government financing during 2010–2019."
    }
  ]
}
